// Lifecycle status of a single connection request.
enum RequestStatus {
    PENDING,  // awaiting a response
    ACCEPTED, // recipient accepted, edge added
    REJECTED  // recipient rejected, no edge
}

// A member of the network and their direct connections.
class User {
    private final String userId;                                    // unique id
    private final String name;                                       // display name
    private final java.util.Set<String> connections = new java.util.HashSet<>(); // directly connected user ids

    public User(String userId, String name) {
        this.userId = userId; // store id
        this.name = name;      // store name
    }

    public String getUserId() { return userId; }                      // id getter
    public String getName() { return name; }                           // name getter
    public java.util.Set<String> getConnections() { return connections; } // connections getter
}

// A request from one user to another to become connections.
class ConnectionRequest {
    private final String requestId;   // unique id
    private final String fromUserId;  // sender
    private final String toUserId;    // recipient
    private RequestStatus status;      // current lifecycle state

    public ConnectionRequest(String requestId, String fromUserId, String toUserId) {
        this.requestId = requestId;   // store id
        this.fromUserId = fromUserId;  // store sender
        this.toUserId = toUserId;      // store recipient
        this.status = RequestStatus.PENDING; // starts pending
    }

    public String getRequestId() { return requestId; }     // id getter
    public String getFromUserId() { return fromUserId; }     // sender getter
    public String getToUserId() { return toUserId; }          // recipient getter
    public RequestStatus getStatus() { return status; }        // status getter
    public void setStatus(RequestStatus status) { this.status = status; } // status setter
}

// Creates connection requests with sequential ids.
class ConnectionRequestFactory {
    private int counter = 0; // running id counter across all requests created

    public ConnectionRequest createRequest(String fromUserId, String toUserId) {
        counter++;                                                       // bump id counter
        return new ConnectionRequest("REQ-" + counter, fromUserId, toUserId); // e.g. REQ-1
    }
}

// A piece of content authored by a user.
class Post {
    private final String postId;    // unique id
    private final String authorId;   // who wrote it
    private final String content;    // post body
    private final int timestamp;      // used for recency ranking

    public Post(String postId, String authorId, String content, int timestamp) {
        this.postId = postId;       // store id
        this.authorId = authorId;    // store author
        this.content = content;       // store content
        this.timestamp = timestamp;    // store timestamp
    }

    public String getPostId() { return postId; }         // id getter
    public String getAuthorId() { return authorId; }       // author getter
    public String getContent() { return content; }          // content getter
    public int getTimestamp() { return timestamp; }           // timestamp getter
}

