// Strategy interface: how candidate posts are ordered into a feed.
interface FeedRankingStrategy {
    java.util.List<Post> rank(java.util.List<Post> candidatePosts);
}

// Orders posts from most recent to least recent.
class RecencyFeedRankingStrategy implements FeedRankingStrategy {
    @Override
    public java.util.List<Post> rank(java.util.List<Post> candidatePosts) {
        java.util.List<Post> sorted = new java.util.ArrayList<>(candidatePosts); // copy to avoid mutating the input
        sorted.sort((a, b) -> b.getTimestamp()-a.getTimestamp());               // descending by timestamp
        return sorted; // most recent first
    }
}

// Observer interface: reacts to network lifecycle events.
interface NetworkObserver {
    void onConnectionRequestSent(ConnectionRequest request);                     // request created
    void onConnectionAccepted(ConnectionRequest request);                         // edge added
    void onConnectionRejected(ConnectionRequest request);                          // request closed, no edge
    void onDuplicateRequestRejected(String fromUserId, String toUserId);            // blocked before creation
}

// Simple observer that prints events to the console.
class ConsoleNetworkObserver implements NetworkObserver {
    @Override
    public void onConnectionRequestSent(ConnectionRequest request) {
        System.out.println("Request " + request.getRequestId() + " sent from " + request.getFromUserId() + " to " + request.getToUserId());
    }

    @Override
    public void onConnectionAccepted(ConnectionRequest request) {
        System.out.println("Request " + request.getRequestId() + " accepted, " + request.getFromUserId() + " and " + request.getToUserId() + " are now connected");
    }

    @Override
    public void onConnectionRejected(ConnectionRequest request) {
        System.out.println("Request " + request.getRequestId() + " rejected");
    }

    @Override
    public void onDuplicateRequestRejected(String fromUserId, String toUserId) {
        System.out.println("Duplicate request rejected between " + fromUserId + " and " + toUserId);
    }
}

