#include <string>
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

// Strategy interface: how candidate posts are ordered into a feed.
class FeedRankingStrategy {
public:
    virtual vector<Post> rank(vector<Post> candidatePosts) = 0;
    virtual ~FeedRankingStrategy() {}
};

// Orders posts from most recent to least recent.
class RecencyFeedRankingStrategy : public FeedRankingStrategy {
public:
    vector<Post> rank(vector<Post> candidatePosts) override {
        vector<Post> sorted = candidatePosts;                                     // copy to avoid mutating the input
        std::sort(sorted.begin(), sorted.end(), [](const Post& a, const Post& b) {  // descending by timestamp
            return a.timestamp > b.timestamp;
        });
        return sorted; // most recent first
    }
};

// Observer interface: reacts to network lifecycle events.
class NetworkObserver {
public:
    virtual void onConnectionRequestSent(const ConnectionRequest& request) = 0;
    virtual void onConnectionAccepted(const ConnectionRequest& request) = 0;
    virtual void onConnectionRejected(const ConnectionRequest& request) = 0;
    virtual void onDuplicateRequestRejected(const string& fromUserId, const string& toUserId) = 0;
    virtual ~NetworkObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleNetworkObserver : public NetworkObserver {
public:
    void onConnectionRequestSent(const ConnectionRequest& request) override {
        cout << "Request " << request.requestId << " sent from " << request.fromUserId << " to " << request.toUserId << endl;
    }
    void onConnectionAccepted(const ConnectionRequest& request) override {
        cout << "Request " << request.requestId << " accepted, " << request.fromUserId << " and " << request.toUserId << " are now connected" << endl;
    }
    void onConnectionRejected(const ConnectionRequest& request) override {
        cout << "Request " << request.requestId << " rejected" << endl;
    }
    void onDuplicateRequestRejected(const string& fromUserId, const string& toUserId) override {
        cout << "Duplicate request rejected between " << fromUserId << " and " << toUserId << endl;
    }
};

