// Custom exceptions for the realistic failure modes.
class DuplicateConnectionException extends RuntimeException {
    public DuplicateConnectionException(String msg) { super(msg); }
}
class InvalidRequestException extends RuntimeException {
    public InvalidRequestException(String msg) { super(msg); }
}
class RequestAlreadyRespondedException extends RuntimeException {
    public RequestAlreadyRespondedException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class NetworkService {
    private final java.util.Map<String, User> users = new java.util.HashMap<>();               // userId -> User
    private final java.util.Map<String, ConnectionRequest> requests = new java.util.HashMap<>(); // requestId -> ConnectionRequest
    private final java.util.Map<String, java.util.List<Post>> posts = new java.util.HashMap<>();  // authorId -> their posts
    private final FeedRankingStrategy rankingStrategy;    // pluggable ranking policy
    private final java.util.List<NetworkObserver> observers = new java.util.ArrayList<>(); // listeners
    private int requestCounter = 0; // simple id generator

    public NetworkService(FeedRankingStrategy rankingStrategy) {
        this.rankingStrategy = rankingStrategy; // store chosen policy
    }

    public void addUser(User user) { users.put(user.getUserId(), user); posts.put(user.getUserId(), new java.util.ArrayList<>()); } // register a user
    public void addObserver(NetworkObserver observer) { observers.add(observer); } // register a listener
    public void addPost(Post post) { posts.get(post.getAuthorId()).add(post); }     // record a post

    private boolean alreadyRelated(String userIdA, String userIdB) {
        if (users.get(userIdA).getConnections().contains(userIdB)) return true; // already connected
        for (ConnectionRequest r : requests.values()) {                          // scan existing requests
            boolean samePair = (r.getFromUserId().equals(userIdA) && r.getToUserId().equals(userIdB))
                    || (r.getFromUserId().equals(userIdB) && r.getToUserId().equals(userIdA));
            if (samePair && r.getStatus() == RequestStatus.PENDING) return true;   // a pending request already exists
        }
        return false; // no existing relationship or pending request
    }

    // Sends a request, rejecting duplicates between an already-related pair.
    public synchronized ConnectionRequest sendConnectionRequest(String fromUserId, String toUserId, ConnectionRequestFactory factory) {
        if (alreadyRelated(fromUserId, toUserId)) {                                // already connected or already pending
            for (NetworkObserver obs : observers) obs.onDuplicateRequestRejected(fromUserId, toUserId); // notify
            throw new DuplicateConnectionException("A request or connection already exists between " + fromUserId + " and " + toUserId);
        }
        ConnectionRequest request = factory.createRequest(fromUserId, toUserId); // build request
        requests.put(request.getRequestId(), request);                             // store it
        for (NetworkObserver obs : observers) obs.onConnectionRequestSent(request); // notify
        return request; // hand back to caller
    }

    // Resolves a pending request, adding an undirected edge only on acceptance.
    public synchronized void respondToRequest(String requestId, boolean accept) {
        ConnectionRequest request = requests.get(requestId);                        // look up request
        if (request == null) throw new InvalidRequestException("Unknown request: " + requestId);
        if (request.getStatus() != RequestStatus.PENDING) {                          // already resolved
            throw new RequestAlreadyRespondedException("Request " + requestId + " was already responded to");
        }
        if (accept) {                                                                  // recipient accepts
            request.setStatus(RequestStatus.ACCEPTED);                                   // mark accepted
            users.get(request.getFromUserId()).getConnections().add(request.getToUserId()); // edge, sender side
            users.get(request.getToUserId()).getConnections().add(request.getFromUserId()); // edge, recipient side
            for (NetworkObserver obs : observers) obs.onConnectionAccepted(request);       // notify
        } else {                                                                        // recipient rejects
            request.setStatus(RequestStatus.REJECTED);                                    // mark rejected, no edge
            for (NetworkObserver obs : observers) obs.onConnectionRejected(request);        // notify
        }
    }

    // Breadth-first search over the undirected connection graph, capped at 3 hops.
    public int getConnectionDegree(String userIdA, String userIdB) {
        if (userIdA.equals(userIdB)) return 0;                                           // same user, degree zero
        java.util.Set<String> visited = new java.util.HashSet<>();                        // nodes already explored
        java.util.Queue<String> queue = new java.util.LinkedList<>();                      // BFS frontier
        java.util.Map<String, Integer> depth = new java.util.HashMap<>();                   // distance from userIdA
        queue.add(userIdA);                                                                 // start BFS here
        visited.add(userIdA);
        depth.put(userIdA, 0);
        while (!queue.isEmpty()) {                                                           // explore level by level
            String current = queue.poll();                                                    // next node
            int currentDepth = depth.get(current);                                              // its distance
            if (currentDepth >= 3) continue;                                                     // do not expand past the cap
            for (String neighbor : users.get(current).getConnections()) {                          // scan its connections
                if (neighbor.equals(userIdB)) return currentDepth + 1;                                // found the target
                if (!visited.contains(neighbor)) {                                                     // first time seeing it
                    visited.add(neighbor);
                    depth.put(neighbor, currentDepth + 1);
                    queue.add(neighbor);
                }
            }
        }
        return 4; // not found within 3 hops: reported as "beyond 3rd degree"
    }

    // Collects posts from 1st-degree connections and ranks them via the configured strategy.
    public java.util.List<Post> generateFeed(String userId) {
        java.util.List<Post> candidates = new java.util.ArrayList<>();                    // gathered posts
        for (String connectionId : users.get(userId).getConnections()) {                   // scan direct connections only
            candidates.addAll(posts.get(connectionId));                                       // include all their posts
        }
        return rankingStrategy.rank(candidates); // delegate ordering to the strategy
    }
}

