#include <string>
#include <vector>
#include <map>
#include <set>
#include <queue>
#include <memory>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class DuplicateConnectionException : public runtime_error {
public: DuplicateConnectionException(const string& msg) : runtime_error(msg) {}
};
class InvalidRequestException : public runtime_error {
public: InvalidRequestException(const string& msg) : runtime_error(msg) {}
};
class RequestAlreadyRespondedException : public runtime_error {
public: RequestAlreadyRespondedException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class NetworkService {
    map<string, User> users;                       // userId -> User
    map<string, ConnectionRequest> requests;       // requestId -> ConnectionRequest
    map<string, vector<Post>> posts;               // authorId -> their posts
    shared_ptr<FeedRankingStrategy> rankingStrategy; // pluggable ranking policy
    vector<shared_ptr<NetworkObserver>> observers;  // listeners
    int requestCounter = 0;                           // simple id generator

    bool alreadyRelated(string userIdA, string userIdB) {
        if (users.at(userIdA).connections.count(userIdB)) return true; // already connected
        for (auto& entry : requests) {                                    // scan existing requests
            ConnectionRequest& r = entry.second;
            bool samePair = (r.fromUserId == userIdA && r.toUserId == userIdB)
                    || (r.fromUserId == userIdB && r.toUserId == userIdA);
            if (samePair && r.status == RequestStatus::PENDING) return true; // a pending request already exists
        }
        return false; // no existing relationship or pending request
    }

public:
    NetworkService(shared_ptr<FeedRankingStrategy> strategy) : rankingStrategy(strategy) {}

    void addUser(User user) { users.insert({user.userId, user}); posts[user.userId] = {}; } // register a user
    void addObserver(shared_ptr<NetworkObserver> observer) { observers.push_back(observer); } // register a listener
    void addPost(Post post) { posts[post.authorId].push_back(post); } // record a post

    ConnectionRequest sendConnectionRequest(string fromUserId, string toUserId, ConnectionRequestFactory& factory) {
        if (alreadyRelated(fromUserId, toUserId)) {                          // already connected or already pending
            for (auto& obs : observers) obs->onDuplicateRequestRejected(fromUserId, toUserId); // notify
            throw DuplicateConnectionException("A request or connection already exists between " + fromUserId + " and " + toUserId);
        }
        ConnectionRequest request = factory.createRequest(fromUserId, toUserId); // build request
        requests.insert({request.requestId, request});                            // store it
        for (auto& obs : observers) obs->onConnectionRequestSent(requests.at(request.requestId)); // notify
        return requests.at(request.requestId); // hand back to caller
    }

    void respondToRequest(string requestId, bool accept) {
        auto it = requests.find(requestId);                                   // look up request
        if (it == requests.end()) throw InvalidRequestException("Unknown request: " + requestId);
        ConnectionRequest& request = it->second;
        if (request.status != RequestStatus::PENDING) {                         // already resolved
            throw RequestAlreadyRespondedException("Request " + requestId + " was already responded to");
        }
        if (accept) {                                                             // recipient accepts
            request.status = RequestStatus::ACCEPTED;                              // mark accepted
            users.at(request.fromUserId).connections.insert(request.toUserId);       // edge, sender side
            users.at(request.toUserId).connections.insert(request.fromUserId);        // edge, recipient side
            for (auto& obs : observers) obs->onConnectionAccepted(request);            // notify
        } else {                                                                    // recipient rejects
            request.status = RequestStatus::REJECTED;                                // mark rejected, no edge
            for (auto& obs : observers) obs->onConnectionRejected(request);            // notify
        }
    }

    int getConnectionDegree(string userIdA, string userIdB) {
        if (userIdA == userIdB) return 0;                                    // same user, degree zero
        set<string> visited;                                                    // nodes already explored
        queue<string> q;                                                          // BFS frontier
        map<string, int> depth;                                                    // distance from userIdA
        q.push(userIdA);                                                             // start BFS here
        visited.insert(userIdA);
        depth[userIdA] = 0;
        while (!q.empty()) {                                                          // explore level by level
            string current = q.front();                                                // next node
            q.pop();
            int currentDepth = depth[current];                                           // its distance
            if (currentDepth >= 3) continue;                                               // do not expand past the cap
            for (auto& neighbor : users.at(current).connections) {                           // scan its connections
                if (neighbor == userIdB) return currentDepth + 1;                              // found the target
                if (!visited.count(neighbor)) {                                                  // first time seeing it
                    visited.insert(neighbor);
                    depth[neighbor] = currentDepth + 1;
                    q.push(neighbor);
                }
            }
        }
        return 4; // not found within 3 hops: reported as "beyond 3rd degree"
    }

    vector<Post> generateFeed(string userId) {
        vector<Post> candidates;                                              // gathered posts
        for (auto& connectionId : users.at(userId).connections) {               // scan direct connections only
            for (auto& post : posts[connectionId]) candidates.push_back(post);    // include all their posts
        }
        return rankingStrategy->rank(candidates); // delegate ordering to the strategy
    }
};

