public class Main {
    public static void main(String[] args) {
        NetworkService service = new NetworkService(new RecencyFeedRankingStrategy());
        service.addObserver(new ConsoleNetworkObserver());
        ConnectionRequestFactory factory = new ConnectionRequestFactory();

        service.addUser(new User("Alice", "Alice"));
        service.addUser(new User("Bob", "Bob"));
        service.addUser(new User("Carol", "Carol"));
        service.addUser(new User("Dave", "Dave"));

        ConnectionRequest r1 = service.sendConnectionRequest("Alice", "Bob", factory);
        service.respondToRequest(r1.getRequestId(), true);

        ConnectionRequest r2 = service.sendConnectionRequest("Bob", "Carol", factory);
        service.respondToRequest(r2.getRequestId(), true);

        try {
            service.sendConnectionRequest("Alice", "Bob", factory);
        } catch (DuplicateConnectionException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        System.out.println("Degree Alice-Bob: " + service.getConnectionDegree("Alice", "Bob"));
        System.out.println("Degree Alice-Carol: " + service.getConnectionDegree("Alice", "Carol"));
