        service.addPost(new Post("P2", "Bob", "Second post", 20));
        service.addPost(new Post("P3", "Carol", "Carol's post", 30));

        List<Post> feed = service.generateFeed("Alice");
        for (Post post : feed) {
            System.out.println("Feed item: " + post.getContent() + " at " + post.getTimestamp());
