    private final Map<String, ConnectionRequest> requests = new HashMap<>();
    private final Map<String, List<Post>> posts = new HashMap<>();
    private final FeedRankingStrategy rankingStrategy;
    private final List<NetworkObserver> observers = new ArrayList<>();
    private int requestCounter = 0;

