        this.rankingStrategy = rankingStrategy;
    }

    public void addUser(User user) { users.put(user.getUserId(), user); posts.put(user.getUserId(), new ArrayList<>()); }
    public void addObserver(NetworkObserver observer) { observers.add(observer); }
    public void addPost(Post post) { posts.get(post.getAuthorId()).add(post); }

    private boolean alreadyRelated(String userIdA, String userIdB) {
        if (users.get(userIdA).getConnections().contains(userIdB)) return true;
        for (ConnectionRequest r : requests.values()) {
            boolean samePair = (r.getFromUserId().equals(userIdA) && r.getToUserId().equals(userIdB))
                    || (r.getFromUserId().equals(userIdB) && r.getToUserId().equals(userIdA));
            if (samePair && r.getStatus() == RequestStatus.PENDING) return true;
        }
        return false;
    }

    public synchronized ConnectionRequest sendConnectionRequest(String fromUserId, String toUserId, ConnectionRequestFactory factory) {
        if (alreadyRelated(fromUserId, toUserId)) {
            for (NetworkObserver obs : observers) obs.onDuplicateRequestRejected(fromUserId, toUserId);
            throw new DuplicateConnectionException("A request or connection already exists between " + fromUserId + " and " + toUserId);
        }
        ConnectionRequest request = factory.createRequest(fromUserId, toUserId);
        requests.put(request.getRequestId(), request);
        for (NetworkObserver obs : observers) obs.onConnectionRequestSent(request);
        return request;
    }

    public synchronized void respondToRequest(String requestId, boolean accept) {
        ConnectionRequest request = requests.get(requestId);
        if (request == null) throw new InvalidRequestException("Unknown request: " + requestId);
        if (request.getStatus() != RequestStatus.PENDING) {
            throw new RequestAlreadyRespondedException("Request " + requestId + " was already responded to");
        }
        if (accept) {
            request.setStatus(RequestStatus.ACCEPTED);
            users.get(request.getFromUserId()).getConnections().add(request.getToUserId());
            users.get(request.getToUserId()).getConnections().add(request.getFromUserId());
            for (NetworkObserver obs : observers) obs.onConnectionAccepted(request);
        } else {
            request.setStatus(RequestStatus.REJECTED);
            for (NetworkObserver obs : observers) obs.onConnectionRejected(request);
        }
    }

    public int getConnectionDegree(String userIdA, String userIdB) {
        if (userIdA.equals(userIdB)) return 0;
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        Map<String, Integer> depth = new HashMap<>();
        queue.add(userIdA);
        visited.add(userIdA);
        depth.put(userIdA, 0);
        while (!queue.isEmpty()) {
            String current = queue.poll();
            int currentDepth = depth.get(current);
            if (currentDepth >= 3) continue;
            for (String neighbor : users.get(current).getConnections()) {
                if (neighbor.equals(userIdB)) return currentDepth + 1;
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    depth.put(neighbor, currentDepth + 1);
                    queue.add(neighbor);
                }
            }
        }
        return 4;
    }

    public List<Post> generateFeed(String userId) {
        List<Post> candidates = new ArrayList<>();
        for (String connectionId : users.get(userId).getConnections()) {
            candidates.addAll(posts.get(connectionId));
        }
        return rankingStrategy.rank(candidates);
    }
}

