    Post(string id, string author, string c, int ts) : postId(id), authorId(author), content(c), timestamp(ts) {}
};

class FeedRankingStrategy {
public:
    virtual vector<Post> rank(vector<Post> candidatePosts) = 0;
    virtual ~FeedRankingStrategy() {}
};

class RecencyFeedRankingStrategy : public FeedRankingStrategy {
public:
    vector<Post> rank(vector<Post> candidatePosts) override {
        vector<Post> sorted = candidatePosts;
        std::sort(sorted.begin(), sorted.end(), [](const Post& a, const Post& b) {
            return a.timestamp > b.timestamp;
        });
        return sorted;
    }
};

class NetworkObserver {
public:
    virtual void onConnectionRequestSent(const ConnectionRequest& request) = 0;
    virtual void onConnectionAccepted(const ConnectionRequest& request) = 0;
    virtual void onConnectionRejected(const ConnectionRequest& request) = 0;
    virtual void onDuplicateRequestRejected(const string& fromUserId, const string& toUserId) = 0;
    virtual ~NetworkObserver() {}
};

